import type { CSSProperties, ReactNode } from "react";
import { clamp } from "../../parts/time";
import { ACCENT, PRIMARY } from "./world";

/**
 * The simulation for "Simulate this box, with sliders for F, m and both μ", in the app's own sim layout (the English
 * template of mathbooklm/bench/results/sim-20261108T205709Z/rc-charging): the stage with the "Answers" cards beside it,
 * the play bar, then the sliders with their typeable value fields and "Question values". Built here, not generated by
 * the app, but the physics is exact: a box released from rest on a level floor, pulled by F. Static friction matches
 * the pull up to μs·m·g, so below that nothing moves; above it the box slides with a = (F − μk·m·g)/m. The run
 * restarts from rest when a value changes, as the app's runtime does.
 */
export const SIM_W = 560;
export const SIM_H = 350;
export const WINDOW = 4; // seconds on the plot
export const G = 10;
export const TITLE = "Box on a floor: static and kinetic friction";

const font = '"Arimo", Arial, sans-serif';
const PUSH = "#9c36b5";
const FRICTION = "#e8590c";
const BLUE = "#1971c2";

export type SimState = { F: number; m: number; mus: number; muk: number; t: number; hot?: Knob; field?: string; changed?: boolean };
export const QUESTION: Omit<SimState, "t"> = { F: 30, m: 5, mus: 0.3, muk: 0.2 };

export function physics({ F, m, mus, muk }: SimState) {
  const N = m * G;
  const fsMax = mus * N;
  const sliding = F > fsMax;
  const f = sliding ? muk * N : F;
  const net = F - f;
  return { N, fsMax, sliding, f, net, a: net / m };
}

export const motion = (s: SimState, t: number) => {
  const p = physics(s);
  return { x: 0.5 * p.a * t * t, v: p.a * t };
};

// ── controls ─────────────────────────────────────────────────────────────────

export const KNOBS = {
  F: { label: "Pull F", y: 244, range: [0, 50], unit: "N", get: (s: SimState) => s.F, fmt: (v: number) => v.toFixed(1) },
  m: { label: "Mass m", y: 270, range: [1, 20], unit: "kg", get: (s: SimState) => s.m, fmt: (v: number) => v.toFixed(1) },
  mus: { label: "Static μs", y: 296, range: [0, 1], unit: "", get: (s: SimState) => s.mus, fmt: (v: number) => v.toFixed(2) },
  muk: { label: "Kinetic μk", y: 322, range: [0, 1], unit: "", get: (s: SimState) => s.muk, fmt: (v: number) => v.toFixed(2) },
} as const;
export type Knob = keyof typeof KNOBS;
const SL = { x: 104, w: 184 };
const FIELD = { x: 298, w: 54 };
const frac = (k: Knob, v: number) => clamp((v - KNOBS[k].range[0]) / (KNOBS[k].range[1] - KNOBS[k].range[0]));
export const thumbAt = (k: Knob, v: number) => ({ x: SL.x + SL.w * frac(k, v), y: KNOBS[k].y });
export const fieldAt = (k: Knob) => ({ x: FIELD.x + FIELD.w / 2, y: KNOBS[k].y });
export const QUESTION_BTN = { x: 430, y: 309, w: 112, h: 26 };

function Slider({ x, y, w, k, hot }: { x: number; y: number; w: number; k: number; hot?: boolean }) {
  return (
    <div style={{ position: "absolute", left: x, top: y - 2, width: w, height: 4, borderRadius: 2, background: "#dcdaf6" }}>
      <div style={{ width: `${k * 100}%`, height: "100%", borderRadius: 2, background: ACCENT }} />
      <div style={{ position: "absolute", left: `calc(${k * 100}% - 7px)`, top: -5, width: 14, height: 14, borderRadius: "50%", background: ACCENT, boxShadow: hot ? `0 0 0 5px rgba(105,101,219,.22)` : undefined }} />
    </div>
  );
}

function Row({ s, k }: { s: SimState; k: Knob }) {
  const K = KNOBS[k];
  const v = K.get(s);
  const t: CSSProperties = { position: "absolute", top: K.y - 8, fontSize: 11, color: "#444", whiteSpace: "nowrap" };
  const editing = s.field !== undefined && s.hot === k;
  return (
    <>
      <span style={{ ...t, left: 12 }}>{K.label}</span>
      <Slider x={SL.x} y={K.y} w={SL.w} k={frac(k, v)} hot={s.hot === k && !editing} />
      <span style={{ position: "absolute", left: FIELD.x, top: K.y - 10, width: FIELD.w, height: 20, boxSizing: "border-box", border: `1px solid ${editing ? ACCENT : "#d6d6dc"}`, boxShadow: editing ? "0 0 0 2px rgba(105,101,219,.2)" : undefined, borderRadius: 4, fontSize: 11, color: "#222", display: "flex", alignItems: "center", justifyContent: "flex-end", padding: "0 5px", background: "#fff" }}>
        {editing ? (
          <>
            <span>{s.field}</span>
            <span style={{ width: 1, height: 12, background: "#222", marginLeft: 1 }} />
          </>
        ) : (
          K.fmt(v)
        )}
      </span>
      <span style={{ ...t, left: FIELD.x + FIELD.w + 7 }}>{K.unit}</span>
    </>
  );
}

function Card({ y, label, value, note }: { y: number; label: string; value: string; note?: string }) {
  return (
    <div style={{ position: "absolute", left: 384, top: y, width: 166, height: 40, padding: "4px 9px", borderRadius: 7, background: "#efeefc", boxSizing: "border-box" }}>
      <div style={{ fontSize: 9, color: "#666", whiteSpace: "nowrap" }}>{label}</div>
      <div style={{ fontSize: 16, fontWeight: 700, color: PRIMARY, marginTop: 1, whiteSpace: "nowrap" }}>
        {value}
        {note && <span style={{ fontSize: 9.5, fontWeight: 600, color: "#666", marginLeft: 5 }}>{note}</span>}
      </div>
    </div>
  );
}

/** An arrow from (x, y) of signed length along one axis. */
function Arrow({ x, y, dx = 0, dy = 0, color, label, lx = 0, ly = 0 }: { x: number; y: number; dx?: number; dy?: number; color: string; label: string; lx?: number; ly?: number }) {
  const len = Math.hypot(dx, dy);
  if (len < 2) return null;
  const ux = dx / len, uy = dy / len;
  const tx = x + dx, ty = y + dy;
  const h = 7;
  return (
    <g>
      <path d={`M${x} ${y}L${tx - ux * h} ${ty - uy * h}`} stroke={color} strokeWidth={2.4} />
      <path d={`M${tx} ${ty}L${tx - ux * h - uy * 4} ${ty - uy * h + ux * 4}L${tx - ux * h + uy * 4} ${ty - uy * h - ux * 4}Z`} fill={color} />
      <text x={tx + lx} y={ty + ly} fontSize={10.5} fontWeight={700} fill={color} fontFamily={font}>{label}</text>
    </g>
  );
}

/** The stage: the box on a floor that scrolls under it, with its four forces; below, v(t). */
function Stage({ s }: { s: SimState }) {
  const p = physics(s);
  const tt = clamp(s.t, 0, WINDOW);
  const { x, v } = motion(s, tt);
  const floor = 92;
  const bx = 140, bw = 76, bh = 52;
  const k = 2.2; // px per newton for the arrows
  const ticks = Array.from({ length: 24 }, (_, i) => i);
  const px = 40; // px per metre
  const off = ((x * px) % 40 + 40) % 40;
  // v(t) plot
  const X0 = 40, X1 = 360, Y0 = 122, Y1 = 186;
  const vmax = 20;
  let d = "";
  const n = Math.max(1, Math.round((tt / WINDOW) * 160));
  for (let j = 0; j <= n; j++) {
    const t = (tt * j) / n;
    const vv = motion(s, t).v;
    d += `${j ? "L" : "M"}${(X0 + ((X1 - X0) * t) / WINDOW).toFixed(1)} ${(Y1 - (clamp(vv, 0, vmax) / vmax) * (Y1 - Y0)).toFixed(1)}`;
  }
  return (
    <svg width={SIM_W} height={196} style={{ position: "absolute", left: 0, top: 0 }} fill="none" fontFamily={font}>
      <path d={`M6 ${floor}H370`} stroke="#495057" strokeWidth={2} />
      {ticks.map((i) => (
        <path key={i} d={`M${6 + i * 16 - (off % 16)} ${floor + 1}l-6 8`} stroke="#adb5bd" strokeWidth={1} />
      ))}
      {Array.from({ length: 10 }, (_, i) => (
        <text key={i} x={10 + i * 40 - off} y={floor + 20} fontSize={8} fill="#adb5bd">{`${Math.floor(x) + i - 3} m`}</text>
      ))}
      <rect x={bx} y={floor - bh} width={bw} height={bh} fill="#fff" stroke="#212529" strokeWidth={1.8} />
      <text x={bx + bw / 2} y={floor - bh / 2 + 4} fontSize={12} fontWeight={700} fill="#212529" textAnchor="middle">{`${s.m.toFixed(0)} kg`}</text>
      <Arrow x={bx + bw} y={floor - bh / 2} dx={s.F * k} color={PUSH} label={`F = ${s.F.toFixed(0)} N`} lx={-30} ly={-8} />
      <Arrow x={bx} y={floor - 4} dx={-p.f * k} color={FRICTION} label={`f = ${p.f.toFixed(0)} N`} lx={-10} ly={-8} />
      <Arrow x={bx + bw / 2} y={floor - bh} dy={-Math.min(p.N * 0.5, 44)} color={BLUE} label="N" lx={6} ly={8} />
      <Arrow x={bx + bw / 2 + 10} y={floor - bh / 2} dy={Math.min(p.N * 0.5, 44)} color={BLUE} label="mg" lx={6} ly={-2} />
      {/* v(t) */}
      <path d={`M${X0} ${Y0}V${Y1}H${X1}`} stroke="#adb5bd" strokeWidth={1} />
      {[0, 10, 20].map((y) => (
        <text key={y} x={X0 - 4} y={Y1 - (y / vmax) * (Y1 - Y0) + 3} fontSize={8.5} fill="#333" textAnchor="end">{y}</text>
      ))}
      {[0, 1, 2, 3, 4].map((t) => (
        <text key={t} x={X0 + ((X1 - X0) * t) / WINDOW} y={Y1 + 10} fontSize={8.5} fill="#666" textAnchor="middle">{t}</text>
      ))}
      <text x={X0 + 4} y={Y0 + 2} fontSize={9.5} fill="#333">v (m/s)</text>
      <text x={X1 - 2} y={Y1 - 4} fontSize={9.5} fill="#333" textAnchor="end">t (s)</text>
      <path d={d} stroke={ACCENT} strokeWidth={2} />
      <circle cx={X0 + ((X1 - X0) * tt) / WINDOW} cy={Y1 - (clamp(v, 0, vmax) / vmax) * (Y1 - Y0)} r={3.4} fill="#f08c00" />
    </svg>
  );
}

/** The sim's page at 560×350. */
export function BoxPage({ s }: { s: SimState }) {
  const p = physics(s);
  const tt = clamp(s.t, 0, WINDOW);
  return (
    <div dir="ltr" style={{ position: "relative", width: SIM_W, height: SIM_H, fontFamily: font, color: "#222", overflow: "hidden" }}>
      <Stage s={s} />
      <div style={{ position: "absolute", left: 384, top: 2, fontSize: 10, color: "#666" }}>Answers</div>
      <Card y={17} label="N = mg" value={`${p.N.toFixed(1)} N`} />
      <Card y={61} label="Friction f" value={`${p.f.toFixed(1)} N`} note={p.sliding ? "kinetic" : "static"} />
      <Card y={105} label="F_net = F − f" value={`${p.net.toFixed(1)} N`} />
      <Card y={149} label="a = F_net / m" value={`${p.a.toFixed(2)} m/s²`} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 200, height: 1, background: "#ececf1" }} />
      <span style={{ position: "absolute", left: 10, top: 206, width: 26, height: 22, borderRadius: 5, border: "1px solid #ddd", display: "grid", placeItems: "center", fontSize: 9, background: "#fff" }}>❚❚</span>
      <span style={{ position: "absolute", left: 40, top: 206, width: 26, height: 22, borderRadius: 5, border: "1px solid #ddd", display: "grid", placeItems: "center", fontSize: 12, color: "#444", background: "#fff" }}>↺</span>
      <span style={{ position: "absolute", left: 76, top: 217, width: 290 }}>
        <Slider x={0} y={0} w={290} k={tt / WINDOW} />
      </span>
      <span style={{ position: "absolute", left: 376, top: 211, fontSize: 10.5, color: "#555" }}>{tt.toFixed(2)} s / {WINDOW.toFixed(2)} s</span>
      <span style={{ position: "absolute", left: 480, top: 206, width: 70, height: 22, border: "1px solid #ccc", borderRadius: 4, fontSize: 10, display: "flex", alignItems: "center", justifyContent: "space-around", boxSizing: "border-box", background: "#fff" }}>
        <span>1×</span>
        <span>▾</span>
      </span>
      {(Object.keys(KNOBS) as Knob[]).map((k) => (
        <Row key={k} s={s} k={k} />
      ))}
      <div style={{ position: "absolute", left: QUESTION_BTN.x, top: QUESTION_BTN.y, width: QUESTION_BTN.w, height: QUESTION_BTN.h, borderRadius: 6, border: "1px solid #e0e0e0", fontSize: 10.5, color: s.changed ? "#333" : "#bbb", display: "grid", placeItems: "center", boxSizing: "border-box", background: "#fff" }}>Question values</div>
    </div>
  );
}

export const SIM_CARD_HEADER = 30;

export function SimCard({ width, s, addHot }: { width: number; s: SimState; addHot?: boolean }) {
  const k = (width - 2) / SIM_W;
  return (
    <div dir="ltr" style={{ width, borderRadius: 10, background: "#f7f7f9", border: "1px solid #e5e7eb", overflow: "hidden", fontFamily: font }}>
      <div style={{ height: SIM_CARD_HEADER, display: "flex", alignItems: "center", gap: 8, padding: "0 10px", fontSize: 11.5, color: "#333" }}>
        <span style={{ flex: 1, fontWeight: 700, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{TITLE}</span>
        <span style={{ color: "#888", fontSize: 10.5 }}>v1</span>
        <span style={{ color: "#888" }}>{"</>"}</span>
        <span style={{ color: "#888" }}>⤢</span>
        <span style={{ color: addHot ? ACCENT : "#666", border: `1px solid ${addHot ? "#c7c5f2" : "#e5e7eb"}`, borderRadius: 6, padding: "1px 7px", background: addHot ? "#eeedfc" : "#fff", whiteSpace: "nowrap" }}>Add to canvas</span>
      </div>
      <div style={{ width: SIM_W, height: SIM_H, transform: `scale(${k})`, transformOrigin: "0 0", marginBottom: SIM_H * (k - 1) }}>
        <BoxPage s={s} />
      </div>
    </div>
  );
}

export function SimBox({ s, active, children }: { s: SimState; active: boolean; children?: ReactNode }) {
  return (
    <div style={{ position: "relative", width: SIM_W, height: SIM_H, outline: active ? `1.5px solid ${ACCENT}` : "1px solid rgba(105,101,219,.18)", outlineOffset: 3 }}>
      <BoxPage s={s} />
      {children}
    </div>
  );
}
